const HOME_GUARD_SWITCHES=[['homeAvoidBbwShotWithoutScale','homeAvoidBbwShotWithoutScaleState','avoidBbwShotWithoutScale','No-scale BBW'],['homeFastExtractionGuardEnabled','homeFastExtractionGuardEnabledState','fastExtractionGuardEnabled','Fast extraction guard'],['homeAvoidAccidentalTouchEnabled','homeAvoidAccidentalTouchEnabledState','avoidAccidentalTouchEnabled','Avoid accidental touch'],['homeSlowExtractionGuardEnabled','homeSlowExtractionGuardEnabledState','slowExtractionGuardEnabled','Slow extraction guard'],['homeAutoToManualGuardEnabled','homeAutoToManualGuardEnabledState','autoToManualGuardEnabled','A→M time guard'],['homeCupProtectionEnabled','homeCupProtectionEnabledState','cupProtectionEnabled','Cup protection']],homeSwitchPending={};
