function updateHomeGuardSwitchesLock(){const bbw=$('homeBrewByWeight'),x=homeSwitchUnset('homeBrewByWeight'),on=!x&&!!bbw&&bbw.checked;if(bbw)bbw.disabled=!controlsMutable||x;HOME_GUARD_SWITCHES.forEach(([h])=>{const el=$(h);if(!el)return;const u=homeSwitchUnset(h),off=!u&&!on;el.disabled=!controlsMutable||u||off;el.closest('.switchRow')?.classList.toggle('fieldOff',off)})}
