function recipeBrewByWeight(){const active=presetState.items.find(x=>x.id===presetState.activeId);return active?!!active.brewByWeight:true}
function selectedPreset(){return presetState.items.find(x=>x.id===(presetState.selectedId||presetState.activeId))}function updatePresetActionButtons(){const p=selectedPreset();const factory=!!(p&&p.isFactory);if($('presetDeleteBtn'))$('presetDeleteBtn').disabled=!controlsMutable||!p||factory;if($('presetResetBtn')){$('presetResetBtn').disabled=!controlsMutable||!factory;$('presetResetBtn').classList.toggle('hidden',!factory)}}async function applyPreset(id,selectable){id=+id;if(!id)return;if(id===presetState.activeId){presetState.selectedId=id;renderAllPresetUi();return}if(selectable){presetState.selectedId=id;renderAllPresetUi();return}if(brewDirty&&!confirm('You have unsaved preset changes. Discard them and switch presets?')){presetState.selectedId=presetState.activeId;renderAllPresetUi();return}brewDirty=false;if($('brewDirtyHint'))$('brewDirtyHint').classList.add('hidden');presetState.selectedId=id;configLoaded=false;formRev=0;await command('/api/v1/presets',{action:'apply',id})}
